const assert = require('node:assert/strict');

        const { Ledger } = require('../.build/ledger');
        const { PaymentService } = require('../.build/service');
        const { Transient } = require('../.build/transport');

        const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
        // Records every acknowledge() call; call n (0-based) throws script[n] when that entry is an Error.
        function transportWith(...script) {
          const calls = [];
          return {
            calls,
            async acknowledge(receipt) {
              calls.push(receipt);
              await sleep(1);
              const outcome = script[calls.length - 1];
              if (outcome instanceof Error) throw outcome;
            },
          };
        }
        // Counts ledger.apply calls so validation can be shown to run before any ledger action.
        function countingLedger() {
          const ledger = new Ledger();
          const apply = ledger.apply.bind(ledger);
          ledger.applyCalls = 0;
          ledger.apply = (...args) => { ledger.applyCalls++; return apply(...args); };
          return ledger;
        }
        const isKeyConflict = e => e instanceof Error && !(e instanceof Transient) && e.message === 'key conflict';

        async function retryChecks() {
          // Transient from acknowledge after the debit committed: retry, forward the same receipt, debit once.
          let ledger = countingLedger();
          let transport = transportWith(new Transient('t1'), new Transient('t2'));
          const receipt = await new PaymentService(ledger, transport).pay('shop', 'retry', 50, 3);
          assert.equal(transport.calls.length, 3);
          assert.equal(ledger.entries.length, 1);
          assert.equal(ledger.applyCalls, 1); // retries re-send the receipt; they do not request the debit again
          for (const forwarded of transport.calls) assert.strictEqual(forwarded, receipt);

          // Exhausted retries rethrow the final Transient itself.
          const last = new Transient('last');
          ledger = new Ledger();
          transport = transportWith(new Transient('a'), new Transient('b'), last);
          const thrown = await new PaymentService(ledger, transport).pay('shop', 'exhaust', 50, 3).then(() => null, e => e);
          assert.strictEqual(thrown, last);
          assert.equal(transport.calls.length, 3);
          assert.equal(ledger.entries.length, 1);

          // Default attempts is 3 total tries.
          transport = transportWith(new Transient('a'), new Transient('b'), new Transient('c'), new Transient('d'));
          await assert.rejects(new PaymentService(new Ledger(), transport).pay('shop', 'default', 50), e => e instanceof Transient);
          assert.equal(transport.calls.length, 3);

          // attempts=1 means exactly one try; attempts=5 allows five.
          transport = transportWith(new Transient('once'));
          await assert.rejects(new PaymentService(new Ledger(), transport).pay('shop', 'one', 50, 1), e => e instanceof Transient);
          assert.equal(transport.calls.length, 1);
          transport = transportWith(new Transient('1'), new Transient('2'), new Transient('3'), new Transient('4'));
          assert.equal((await new PaymentService(new Ledger(), transport).pay('shop', 'five', 50, 5)).cents, 50);
          assert.equal(transport.calls.length, 5);

          // A Transient raised before the debit commits is retried, and the debit still happens once.
          const flaky = new Ledger(); const realApply = flaky.apply.bind(flaky); let applyTries = 0;
          flaky.apply = async (...args) => { if (applyTries++ === 0) throw new Transient('before commit'); return realApply(...args); };
          await new PaymentService(flaky, transportWith()).pay('shop', 'pre-commit', 50, 2);
          assert.equal(applyTries, 2);
          assert.equal(flaky.entries.length, 1);

          // Non-Transient errors are not retried and propagate unchanged.
          const boom = new Error('boom');
          transport = transportWith(boom);
          await assert.rejects(new PaymentService(new Ledger(), transport).pay('shop', 'other', 50, 5), e => e === boom);
          assert.equal(transport.calls.length, 1);
        }

        async function idempotencyChecks() {
          // Sequential repeat with equal amount returns the original receipt without a second debit.
          let ledger = new Ledger();
          let transport = transportWith();
          let service = new PaymentService(ledger, transport);
          const first = await service.pay('shop', 'dup', 75);
          const second = await service.pay('shop', 'dup', 75);
          assert.strictEqual(second, first);
          assert.equal(ledger.entries.length, 1);

          // Same tenant/key with another amount: key conflict, no debit, no acknowledgement.
          await assert.rejects(service.pay('shop', 'dup', 76), isKeyConflict);
          assert.equal(ledger.entries.length, 1);
          assert.equal(transport.calls.length, 2);

          // A key conflict is not retried, even with attempts remaining.
          const counted = countingLedger(); const conflictService = new PaymentService(counted, transportWith());
          await conflictService.pay('shop', 'conflict-once', 10, 5);
          await assert.rejects(conflictService.pay('shop', 'conflict-once', 11, 5), isKeyConflict);
          assert.equal(counted.applyCalls, 2);
          assert.equal(counted.entries.length, 1);

          // Scoping: same key under another tenant is a separate debit; separators cannot collide.
          ledger = new Ledger(); service = new PaymentService(ledger, transportWith());
          await service.pay('t1', 'k', 5);
          await service.pay('t2', 'k', 9);
          const c = await service.pay('a:b', 'c', 1);
          const d = await service.pay('a', 'b:c', 1);
          assert.equal(ledger.entries.length, 4);
          assert.notEqual(c.id, d.id);

          // Concurrent equal-amount calls: one debit, every caller gets the same receipt.
          ledger = new Ledger(); service = new PaymentService(ledger, transportWith());
          const same = await Promise.all(Array.from({ length: 10 }, () => service.pay('shop', 'race', 40)));
          assert.equal(ledger.entries.length, 1);
          for (const r of same) assert.strictEqual(r, same[0]);

          // Concurrent calls where the first acknowledgement is Transient: still one debit.
          ledger = new Ledger(); service = new PaymentService(ledger, transportWith(new Transient('once')));
          const retried = await Promise.all([1, 2, 3].map(() => service.pay('shop', 'race2', 40)));
          assert.equal(ledger.entries.length, 1);
          for (const r of retried) assert.strictEqual(r, retried[0]);

          // Concurrent calls with different amounts: one wins, the other is a key conflict with no debit.
          ledger = new Ledger(); service = new PaymentService(ledger, transportWith());
          const settled = await Promise.allSettled([service.pay('shop', 'mix', 40), service.pay('shop', 'mix', 41)]);
          assert.equal(settled.filter(s => s.status === 'fulfilled').length, 1);
          assert.ok(isKeyConflict(settled.find(s => s.status === 'rejected').reason));
          assert.equal(ledger.entries.length, 1);

          // Ledger.apply directly: a repeat returns the stored receipt; a different amount conflicts.
          ledger = new Ledger();
          const stored = await ledger.apply('shop', 'direct', 3);
          assert.strictEqual(await ledger.apply('shop', 'direct', 3), stored);
          await assert.rejects(ledger.apply('shop', 'direct', 4), isKeyConflict);
          assert.equal(ledger.entries.length, 1);
        }

        async function validationChecks() {
          const badPayments = [
            ['', 'k', 1], ['t', '', 1], [undefined, 'k', 1], [null, 'k', 1], [7, 'k', 1], ['t', 7, 1],
            ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', NaN], ['t', 'k', Infinity], ['t', 'k', '5'],
          ];
          for (const [tenant, key, cents] of badPayments) {
            const ledger = countingLedger(); const transport = transportWith();
            await assert.rejects(new PaymentService(ledger, transport).pay(tenant, key, cents), /invalid payment/);
            assert.equal(ledger.applyCalls, 0); assert.equal(transport.calls.length, 0);
          }
          for (const attempts of [0, 6, -1, 1.5, NaN, Infinity, '2', null]) {
            const ledger = countingLedger(); const transport = transportWith();
            await assert.rejects(new PaymentService(ledger, transport).pay('t', 'k', 1, attempts), /invalid payment/);
            assert.equal(ledger.applyCalls, 0); assert.equal(transport.calls.length, 0);
          }
          // Boundary values that are valid.
          assert.equal((await new PaymentService(new Ledger(), transportWith()).pay('t', 'k', 1, 1)).cents, 1);
          assert.equal((await new PaymentService(new Ledger(), transportWith()).pay('t', 'k2', 1, 5)).cents, 1);
        }

        async function main() {
          const ledger = new Ledger(); const receipts = [];
          const service = new PaymentService(ledger, { acknowledge: async r => { receipts.push(r); } });
          assert.deepEqual(await service.pay('shop', 'sale', 123), { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
          assert.equal(ledger.entries.length, 1); assert.equal(receipts.length, 1);
          await assert.rejects(service.pay('shop', 'bad', 0), /invalid payment/);
          await retryChecks();
          await idempotencyChecks();
          await validationChecks();
        }
        module.exports = main();

