export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // tenant -> key -> the first debit committed under that pair. Nested maps keep tenant and key unambiguous.
  readonly #debits = new Map<string, Map<string, { cents: number; receipt: Receipt }>>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // No await between the lookup and the commit, so concurrent callers cannot interleave here.
    let byKey = this.#debits.get(tenant);
    if (!byKey) { byKey = new Map(); this.#debits.set(tenant, byKey); }
    const existing = byKey.get(key);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing.receipt;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    byKey.set(key, { cents, receipt });
    return receipt;
  }
}

