import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';
const isNonEmptyString = (value: unknown): boolean => typeof value === 'string' && value.length > 0;
export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    if (!isNonEmptyString(tenant) || !isNonEmptyString(key) || !Number.isInteger(cents) || cents <= 0 ||
        !Number.isInteger(attempts) || attempts < 1 || attempts > 5) throw new Error('invalid payment');
    let receipt: Receipt | undefined;
    for (let tries = 1; ; tries++) {
      try {
        // The ledger is idempotent per tenant/key; holding the receipt means later tries forward the same one.
        receipt ??= await this.ledger.apply(tenant, key, cents);
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        if (!(error instanceof Transient) || tries >= attempts) throw error;
      }
    }
  }
}
